+    h.execute(&world, EditOperationParams::new(&world, "Burn1", next).expect("edit"));
+    h.execute(&world, GenerateOperation::new(&world, "Burn1").expect("burns to the floor"));
+    assert!((feed_tip(&world, "Burn1") - (14.0 + GAP)).abs() < 1e-9);
