+    h.execute(&world, EditOperationParams::new(&world, "Burn1", burn(SinkerDatum::ElectrodeTip, 11.0, 14.0)).expect("edit"));
+    h.execute(&world, GenerateOperation::new(&world, "Burn1").expect("burns"));
