+//! Sinker EDM burn to depth (#541): one electrode fed straight down Z
+//! to a stated depth, measured from a stated datum - the plunge as CL
+//! moves, so the 3-axis stock sim verifies exactly what posts (#290 D3,
+//! D7).
+//!
+//! Provenance: general die-sink EDM practice from public machine-tool
+//! handbooks - the electrode positioned over the cavity, fed down Z
+//! under servo control to depth, retracted along the same axis; the
+//! datum readings and the refusals are our own design (#290 D1-D10).
+//! No vendor material.
+//!
+//! The path: a rapid to the approach plane over the burn point, a feed
+//! plunge to the burn floor, a rapid retract back up the same axis.
+//! Nothing here guesses: a depth that is not a positive finite number,
+//! a burn floor below the stated floor datum or below the model's
+//! floor, a burn deeper than the electrode is long, or an approach
+//! plane at or below the floor - each is refused by name.
+
+use crate::cl::{MoveKind, PathBuilder, Toolpath};
+use crate::geometry::Point3;
+use crate::machining2d::GenError;
+
+/// Where a burn's depth is measured from.
+#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
+pub enum SinkerDatum {
+    /// Down from the work's top: the burn floor is `top - depth`.
+    #[default]
+    WorkTop,
+    /// Up from the cavity floor: the burn floor is `floor + depth` -
+    /// `depth` is what is left standing above the floor (0 burns
+    /// exactly to it). A negative stand-off would be past the floor.
+    CavityFloor,
+    /// Down from the electrode tip as it stands at the approach plane:
+    /// the burn floor is `approach - depth`.
+    ElectrodeTip,
+}
+
+impl SinkerDatum {
+    /// The datum in the words a refusal or a note names.
+    #[must_use]
+    pub fn label(self) -> &'static str {
+        match self {
+            SinkerDatum::WorkTop => "work top",
+            SinkerDatum::CavityFloor => "cavity floor",
+            SinkerDatum::ElectrodeTip => "electrode tip",
+        }
+    }
+}
+
+/// The burn's resolved numbers, world mm.
+#[derive(Clone, Copy, Debug, PartialEq)]
+pub struct SinkerParams {
+    /// The face centre the electrode burns at.
+    pub x: f64,
+    pub y: f64,
+    /// The approach / retract plane the electrode tip travels on.
+    pub approach_z: f64,
+    /// The work's top.
+    pub top_z: f64,
+    /// The cavity floor datum - the burn never passes it.
+    pub floor_z: f64,
+    /// The model's floor under the electrode, when one is known: the
+    /// burn never passes it either.
+    pub model_floor_z: Option<f64>,
+    pub datum: SinkerDatum,
+    pub depth: f64,
+    /// The electrode's length below its holder: the burn never buries
+    /// more than this below the work top.
+    pub electrode_len: f64,
+    /// The servo feed down, mm/min.
+    pub feed: f64,
+    /// The spark gap per side of the machine's condition (#531), mm:
+    /// the cavity stands this far beyond the electrode's face, so the
+    /// tip stops this far above the burn floor.
+    pub gap: f64,
+    /// How far above the finished floor the tip stops, when an
+    /// undersize law places it (#543: the electrode's undersize per
+    /// side, `sinker_undersize::judge`); `None` stops it one spark gap
+    /// above (#541). Never less than the gap - that would burn past the
+    /// floor.
+    pub stand: Option<f64>,
+}
+
+/// Slack under which a floor reading counts as "on" the floor, mm.
+const ON_FLOOR: f64 = 1e-6;
+
+/// The burn floor `depth` reaches from the stated datum: the cavity's
+/// floor as burned (the electrode tip stops one spark gap above it).
+#[must_use]
+pub fn burn_floor(p: &SinkerParams) -> f64 {
+    match p.datum {
+        SinkerDatum::WorkTop => p.top_z - p.depth,
+        SinkerDatum::CavityFloor => p.floor_z + p.depth,
+        SinkerDatum::ElectrodeTip => p.approach_z - p.depth,
+    }
+}
+
+/// Every refusal of the burn, by name, before a move is built.
+fn check(p: &SinkerParams) -> Result<f64, GenError> {
+    let nums = [p.x, p.y, p.approach_z, p.top_z, p.floor_z, p.depth, p.electrode_len, p.feed, p.gap];
+    if !nums.iter().all(|v| v.is_finite())
+        || p.model_floor_z.is_some_and(|z| !z.is_finite())
+        || p.stand.is_some_and(|s| !s.is_finite())
+    {
+        return Err(GenError::Invalid("sinker burn: a position, height or depth is not a finite number".into()));
+    }
+    if p.depth < 0.0 || (p.depth == 0.0 && p.datum != SinkerDatum::CavityFloor) {
+        return Err(GenError::Invalid(format!(
+            "sinker burn: a depth of {} from the {} burns nothing - state a positive depth",
+            p.depth,
+            p.datum.label()
+        )));
+    }
+    if p.gap < 0.0 {
+        return Err(GenError::Invalid(format!("sinker burn: the condition's spark gap {} is negative", p.gap)));
+    }
+    if let Some(s) = p.stand
+        && s < p.gap - ON_FLOOR
+    {
+        return Err(GenError::Invalid(format!(
+            "sinker burn: the tip would stand {s:.3} above the floor, inside its {:.3} spark gap - the floor would burn past size",
+            p.gap
+        )));
+    }
+    if p.feed <= 0.0 {
+        return Err(GenError::Invalid(format!("sinker burn: the servo feed {} must be positive", p.feed)));
+    }
+    if p.floor_z > p.top_z {
+        return Err(GenError::Invalid(format!(
+            "sinker burn: the cavity floor datum ({:.3}) stands above the work top ({:.3})",
+            p.floor_z, p.top_z
+        )));
+    }
+    let z = burn_floor(p);
+    if z < p.floor_z - ON_FLOOR {
+        return Err(GenError::Invalid(format!(
+            "sinker burn: a depth of {} from the {} reaches Z {z:.3}, past the cavity floor datum at Z {:.3}",
+            p.depth,
+            p.datum.label(),
+            p.floor_z
+        )));
+    }
+    if let Some(m) = p.model_floor_z
+        && z < m - ON_FLOOR
+    {
+        return Err(GenError::Invalid(format!(
+            "sinker burn: a depth of {} from the {} reaches Z {z:.3}, past the model's floor at Z {m:.3}",
+            p.depth,
+            p.datum.label()
+        )));
+    }
+    if z >= p.top_z {
+        return Err(GenError::Invalid(format!(
+            "sinker burn: the burn floor Z {z:.3} does not enter the work (its top is Z {:.3})",
+            p.top_z
+        )));
+    }
+    if p.approach_z <= p.top_z {
+        return Err(GenError::Invalid(format!(
+            "sinker burn: the approach plane Z {:.3} must stand above the work top Z {:.3}",
+            p.approach_z, p.top_z
+        )));
+    }
+    let tip = z + stand(p);
+    let buried = p.top_z - tip;
+    if buried > p.electrode_len + ON_FLOOR {
+        return Err(GenError::Invalid(format!(
+            "sinker burn: the burn reaches {buried:.3} below the work top, but the electrode is only {:.3} long - its holder would enter the work",
+            p.electrode_len
+        )));
+    }
+    Ok(z)
+}
+
+/// How far above the burn floor the tip stops: the stated stand-off
+/// (#543's undersize), else one spark gap (#541).
+#[must_use]
+pub fn stand(p: &SinkerParams) -> f64 {
+    p.stand.unwrap_or(p.gap)
+}
+
+/// Where the electrode tip stops: [`stand`] above the burn floor.
+#[must_use]
+pub fn tip_z(p: &SinkerParams) -> f64 {
+    burn_floor(p) + stand(p)
+}
+
+/// The burn: approach over the point, feed the tip down to one spark
+/// gap above the burn floor at the servo feed, retract up the same
+/// axis. The moves are the electrode TIP's path (the face centre).
+pub fn burn_to_depth(p: &SinkerParams) -> Result<Toolpath, GenError> {
+    let z = check(p)?;
+    let tip = z + stand(p);
+    let mut b = PathBuilder::approached(Point3::new(p.x, p.y, p.approach_z));
+    b.push(MoveKind::Feed, Point3::new(p.x, p.y, tip), Some(p.feed));
+    b.push(MoveKind::Rapid, Point3::new(p.x, p.y, p.approach_z), None);
+    b.note(format!(
+        "sinker burn: {} from the {} to Z {z:.3}, tip at Z {tip:.3} (spark gap {:.3}; cavity floor datum Z {:.3})",
+        p.depth,
+        p.datum.label(),
+        p.gap,
+        p.floor_z
+    ));
+    Ok(b.finish())
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    fn params() -> SinkerParams {
+        SinkerParams {
+            x: 0.0,
+            y: 0.0,
+            approach_z: 25.0,
+            top_z: 20.0,
+            floor_z: 10.0,
+            model_floor_z: Some(0.0),
+            datum: SinkerDatum::WorkTop,
+            depth: 6.0,
+            electrode_len: 30.0,
+            feed: 40.0,
+            gap: 0.0,
+            stand: None,
+        }
+    }
+
+    #[test]
+    fn sinker_burn_reads_each_datum() {
+        let mut p = params();
+        assert_eq!(burn_floor(&p), 14.0);
+        p.datum = SinkerDatum::CavityFloor;
+        p.depth = 0.5;
+        assert_eq!(burn_floor(&p), 10.5);
+        p.datum = SinkerDatum::ElectrodeTip;
+        p.depth = 12.0;
+        assert_eq!(burn_floor(&p), 13.0);
+        let path = burn_to_depth(&p).expect("burns");
+        let feeds: Vec<_> = path.moves.iter().filter(|m| m.kind == MoveKind::Feed).collect();
+        assert_eq!(feeds.len(), 1);
+        assert_eq!(feeds[0].to.z, 13.0);
+        p.gap = 0.25;
+        let path = burn_to_depth(&p).expect("burns");
+        assert!(path.moves.iter().any(|m| m.kind == MoveKind::Feed && m.to.z == 13.25));
+        assert_eq!(path.moves.first().map(|m| m.kind), Some(MoveKind::Rapid));
+    }
+
+    #[test]
+    fn sinker_burn_refuses_past_the_floor_by_name() {
+        let mut p = params();
+        p.depth = 10.5; // 20 - 10.5 = 9.5 < floor 10
+        let e = burn_to_depth(&p).expect_err("past the floor");
+        assert!(e.to_string().contains("past the cavity floor datum"), "{e}");
+        p.floor_z = -5.0;
+        p.depth = 21.0; // Z -1 < model floor 0
+        let e = burn_to_depth(&p).expect_err("past the model");
+        assert!(e.to_string().contains("past the model's floor"), "{e}");
+        p.model_floor_z = None;
+        p.electrode_len = 10.0;
+        p.depth = 12.0;
+        let e = burn_to_depth(&p).expect_err("buried holder");
+        assert!(e.to_string().contains("only 10.000 long"), "{e}");
+    }
+}

@@ -0,0 +1,311 @@
+//! A sinker EDM cavity read from picked part faces (#547): one level
+//! floor and the vertical walls standing on every edge of it, checked
+//! face by face and edge by edge, and refused by name for anything
+//! else: nothing is guessed from a face set that does not spell one
+//! cavity.
+//!
+//! Provenance: our own reading over the planar-face boundary
+//! representation this repo machines from, by the published
+//! depression-feature rule (a pocket is a face whose boundary edges are
+//! concave: Joshi & Chang, "Graph-based heuristics for recognition of
+//! machined features from a 3D solid model", CAD 20(2), 1988), with
+//! Newell's method for a planar ring's vector area (Sutherland, Sproull
+//! & Schumacker, "A characterization of ten hidden-surface algorithms",
+//! ACM Computing Surveys 6(1), 1974). General die-sink EDM practice from
+//! public machine-tool handbooks: the electrode is the cavity's shape,
+//! fed down Z. No vendor material.
+//!
+//! Robustness (Prime Directive): total on any input. A non-finite or
+//! out-of-range coordinate, a face with no area, a boundary that does
+//! not close, a curved or leaning wall, a second floor, a wall of
+//! another cavity, or a floor edge no wall stands on is each a refusal
+//! that names the face; no arithmetic runs on an unchecked number.
+
+use crate::geo2d::Point2;
+use crate::geometry::Point3;
+use crate::machining2d::GenError;
+
+/// Two points this close are the same point, mm (1 nm: the weld lattice
+/// of `geometry::feature`).
+pub const TOL: f64 = 1e-6;
+/// A unit normal this close to +Z is level.
+const LEVEL: f64 = 0.999_999;
+/// A unit normal with |z| under this is vertical.
+const VERTICAL: f64 = 1e-6;
+/// A ring under this area bounds nothing, mm².
+const MIN_AREA: f64 = 1e-9;
+/// The least rise of a wall above its floor, mm.
+pub const MIN_DEPTH: f64 = 1e-3;
+/// Coordinates beyond this are no part on any machine, mm - and the
+/// bound that keeps every product below finite.
+const COORD_LIMIT: f64 = 1e6;
+
+/// One picked face, in world coordinates.
+#[derive(Clone, Debug, PartialEq)]
+pub struct PickedFace {
+    /// How a refusal names it ("face 0x12ab of 'part'").
+    pub label: String,
+    /// The outward unit normal by the facets' winding: it points into
+    /// the air, so into the cavity for a cavity's own faces.
+    pub normal: Point3,
+    /// A welded smooth (curved) face rather than one plane.
+    pub curved: bool,
+    /// Its boundary refused to close into rings.
+    pub open: bool,
+    /// The outer boundary ring, in order (either winding).
+    pub outer: Vec<Point3>,
+}
+
+/// One cavity: its floor's outline and the heights its walls span.
+#[derive(Clone, Debug, PartialEq)]
+pub struct Cavity {
+    /// The floor's outer ring in world XY, counter-clockwise from above.
+    pub outline: Vec<Point2>,
+    pub floor_z: f64,
+    /// The highest point of the picked walls: the cavity's mouth.
+    pub top_z: f64,
+    /// How many walls stand on the floor.
+    pub walls: usize,
+}
+
+fn refuse<T>(why: String) -> Result<T, GenError> {
+    Err(GenError::Invalid(format!("electrode from faces: {why}")))
+}
+
+fn in_range(p: Point3) -> bool {
+    p.is_finite() && p.x.abs() < COORD_LIMIT && p.y.abs() < COORD_LIMIT && p.z.abs() < COORD_LIMIT
+}
+
+/// Newell's vector area of a ring: its length is the ring's area, its
+/// direction the ring's plane normal.
+fn vector_area(ring: &[Point3]) -> Point3 {
+    let Some(&o) = ring.first() else { return Point3::ZERO };
+    let mut s = Point3::ZERO;
+    for w in ring.windows(2) {
+        if let [a, b] = w {
+            let c = (*a - o).cross(*b - o);
+            s = Point3::new(s.x + c.x, s.y + c.y, s.z + c.z);
+        }
+    }
+    Point3::new(0.5 * s.x, 0.5 * s.y, 0.5 * s.z)
+}
+
+/// Every refusal one face can earn on its own, by name.
+fn check_face(f: &PickedFace) -> Result<(), GenError> {
+    let l = &f.label;
+    if f.curved {
+        return refuse(format!(
+            "{l} is a curved wall - an electrode is generated from planar walls only (a non-planar wall is not modelled)"
+        ));
+    }
+    if f.open || f.outer.len() < 3 {
+        return refuse(format!("{l} has an open loop - its boundary does not close, so it bounds no face"));
+    }
+    if !f.normal.is_finite() || !f.outer.iter().all(|p| p.is_finite()) {
+        return refuse(format!("{l} has a coordinate that is not a finite number"));
+    }
+    if !f.outer.iter().copied().all(in_range) {
+        return refuse(format!("{l} lies outside the machinable range ({COORD_LIMIT:e} mm)"));
+    }
+    let len = f.normal.dot(f.normal).sqrt();
+    if (len - 1.0).abs() > 1e-6 {
+        return refuse(format!("{l} has no usable normal - re-pick it"));
+    }
+    let Some(&o) = f.outer.first() else {
+        return refuse(format!("{l} has an open loop - its boundary does not close, so it bounds no face"));
+    };
+    if let Some(off) = f.outer.iter().map(|p| (*p - o).dot(f.normal).abs()).find(|d| *d > 10.0 * TOL) {
+        return refuse(format!(
+            "{l} is not planar - its boundary leaves its plane by {off:.6} mm (a non-planar wall is not modelled)"
+        ));
+    }
+    let a = vector_area(&f.outer);
+    if a.dot(a).sqrt() < MIN_AREA {
+        return refuse(format!("{l} has zero area - it bounds nothing"));
+    }
+    Ok(())
+}
+
+fn xy(p: Point3) -> Point2 {
+    Point2::new(p.x, p.y)
+}
+
+/// The floor ring in world XY, counter-clockwise from above, with
+/// repeated points dropped.
+fn floor_ring(f: &PickedFace) -> Vec<Point2> {
+    let mut pts: Vec<Point2> = Vec::with_capacity(f.outer.len());
+    for p in f.outer.iter().copied().map(xy) {
+        if pts.last().is_none_or(|q| (q.x - p.x).hypot(q.y - p.y) > TOL) {
+            pts.push(p);
+        }
+    }
+    if pts.len() > 1 && pts.first().zip(pts.last()).is_some_and(|(a, b)| (a.x - b.x).hypot(a.y - b.y) <= TOL) {
+        pts.pop();
+    }
+    let n = pts.len();
+    let signed: f64 = (0..n)
+        .filter_map(|i| Some((pts.get(i)?, pts.get((i + 1) % n)?)))
+        .map(|(a, b)| a.x * b.y - b.x * a.y)
+        .sum();
+    if signed < 0.0 {
+        pts.reverse();
+    }
+    pts
+}
+
+/// One wall's stand on the floor ring: the spans `(edge, from, to)` in
+/// mm along each floor edge its bottom edge runs on.
+fn stand_of(w: &PickedFace, ring: &[Point2], floor_z: f64) -> Result<Vec<(usize, f64, f64)>, GenError> {
+    let l = &w.label;
+    let (lo, hi) = w.outer.iter().fold((f64::INFINITY, f64::NEG_INFINITY), |(lo, hi), p| (lo.min(p.z), hi.max(p.z)));
+    if lo < floor_z - TOL {
+        return refuse(format!(
+            "{l} reaches Z {lo:.3}, below the picked floor at Z {floor_z:.3} - it is not a wall of this cavity (faces from different cavities?)"
+        ));
+    }
+    if hi < floor_z + MIN_DEPTH {
+        return refuse(format!("{l} does not rise above the picked floor at Z {floor_z:.3} - it is not a wall of this cavity"));
+    }
+    let m = w.outer.len();
+    let bottoms: Vec<(Point2, Point2)> = (0..m)
+        .filter_map(|i| Some((*w.outer.get(i)?, *w.outer.get((i + 1) % m)?)))
+        .filter(|(p, q)| (p.z - floor_z).abs() <= TOL && (q.z - floor_z).abs() <= TOL)
+        .map(|(p, q)| (xy(p), xy(q)))
+        .collect();
+    let n = ring.len();
+    let mut spans = Vec::new();
+    for i in 0..n {
+        let (Some(&a), Some(&b)) = (ring.get(i), ring.get((i + 1) % n)) else { continue };
+        let len = (b.x - a.x).hypot(b.y - a.y);
+        if len <= TOL {
+            continue;
+        }
+        let u = ((b.x - a.x) / len, (b.y - a.y) / len);
+        for (p, q) in &bottoms {
+            let off = |r: &Point2| (u.0 * (r.y - a.y) - u.1 * (r.x - a.x)).abs();
+            if off(p) > TOL || off(q) > TOL {
+                continue;
+            }
+            let along = |r: &Point2| u.0 * (r.x - a.x) + u.1 * (r.y - a.y);
+            let (tp, tq) = (along(p), along(q));
+            let (from, to) = (tp.min(tq).max(0.0), tp.max(tq).min(len));
+            if to - from <= TOL {
+                continue;
+            }
+            // Into the cavity is the left of a counter-clockwise ring.
+            if w.normal.x * -u.1 + w.normal.y * u.0 < LEVEL {
+                return refuse(format!(
+                    "{l} stands on the picked floor but faces away from it - it is the outside of a boss or of another cavity, not a wall of this one"
+                ));
+            }
+            spans.push((i, from, to));
+        }
+    }
+    if spans.is_empty() {
+        return refuse(format!(
+            "{l} does not stand on the picked floor - it is a face of a different cavity (or no wall of this one)"
+        ));
+    }
+    Ok(spans)
+}
+
+/// The cavity a face set spells: exactly one level floor facing up, and
+/// vertical planar walls standing on every edge of its outer ring.
+///
+/// # Errors
+/// By name: no faces; a face that is curved, open, non-finite, out of
+/// range, non-planar, zero-area, leaning or facing down; no floor or
+/// more than one; no walls; a wall of another cavity; a floor edge with
+/// no wall (the walls do not close).
+pub fn cavity_of(faces: &[PickedFace]) -> Result<Cavity, GenError> {
+    if faces.is_empty() {
+        return refuse("no faces are picked - pick the cavity's floor and the walls standing on it".into());
+    }
+    let (mut floors, mut walls) = (Vec::new(), Vec::new());
+    for f in faces {
+        check_face(f)?;
+        let nz = f.normal.z;
+        if nz >= LEVEL {
+            floors.push(f);
+        } else if nz.abs() <= VERTICAL {
+            walls.push(f);
+        } else if nz <= -LEVEL {
+            return refuse(format!("{} faces down - a cavity's floor faces up and its walls are vertical", f.label));
+        } else {
+            return refuse(format!(
+                "{} leans {:.3} degrees off vertical - a drafted wall or a tilted floor is not modelled",
+                f.label,
+                nz.abs().min(1.0).asin().to_degrees()
+            ));
+        }
+    }
+    let floor = match floors.as_slice() {
+        [one] => *one,
+        [] => return refuse("no floor is picked - pick the cavity's level floor with its walls".into()),
+        many => {
+            let names: Vec<&str> = many.iter().map(|f| f.label.as_str()).collect();
+            return refuse(format!(
+                "{} floors are picked ({}) - one cavity has one level floor; these are faces from different cavities, or a stepped cavity, which is not modelled",
